-- 00_PRECHECK_CLOUD.sql — READ-ONLY 선판정 [E20260930-DMF0020FXZERO] · 빌드 2026-09-30 20:59 · 원천 사내 ZIOUI1
--  ⚠ QA · DEV 두 DB 모두 · JUDGE 가 '적용'/'SKIP' 이 아니면 11 을 적용하지 말고 12 수동 반영(README §4)
SET PAGESIZE 200 LINESIZE 250
COLUMN JUDGE FORMAT A90
PROMPT [E0] 접속 DB
SELECT USER USR, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, SYS_CONTEXT('USERENV','SERVER_HOST') HOST FROM DUAL;
PROMPT [H0] SPEC 선판정 — P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE 선언이 없으면 10 을 먼저 적용 (없이 11 적용 시 PLS-00313)
SELECT (SELECT COUNT(*) FROM USER_PROCEDURES WHERE OBJECT_NAME='PKG_DMF0020' AND PROCEDURE_NAME='P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE') SINGLE_DECL,
       (SELECT COUNT(*) FROM USER_PROCEDURES WHERE OBJECT_NAME='PKG_DMF0020' AND PROCEDURE_NAME IS NOT NULL) SPEC_PROC_CNT,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0020' AND OBJECT_TYPE='PACKAGE') SPEC_STATUS,
       CASE WHEN (SELECT COUNT(*) FROM USER_PROCEDURES WHERE OBJECT_NAME='PKG_DMF0020' AND PROCEDURE_NAME='P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE') = 1
            THEN 'SPEC OK — 10 생략 가능 (11 만)' ELSE '⚠ SPEC 구세대 — 05 → 10 → 11 → 13 → 90 순서로' END JUDGE
  FROM DUAL;
PROMPT [H0-1] 클라우드 SPEC 에만 있는 프로시저 (사내 SPEC 21 개 외) — 1건이라도 있으면 10 적용 전 회신 (타 호출처 파손 위험)
SELECT PROCEDURE_NAME CLOUD_ONLY_PROC FROM USER_PROCEDURES WHERE OBJECT_NAME='PKG_DMF0020' AND PROCEDURE_NAME IS NOT NULL
   AND PROCEDURE_NAME NOT IN ('P_DMF0000_SAVE_EXCHANGE_POPUP_DATA', 'P_DMF0020_EXCEL_UPLOAD', 'P_DMF0020_GET_EXCHANGE_POPUP_SPREAD_TITLE', 'P_DMF0020_GET_FUTUREPRICE_INFO', 'P_DMF0020_GET_MEASURE_COUNTINFO', 'P_DMF0020_GET_MEASURE_COUNTINFO_SAVE_PRICE', 'P_DMF0020_GET_OWNER_DATA', 'P_DMF0020_GET_SALES_PRICE_TEMPLATE', 'P_DMF0020_GET_SCM_MST_FUTURE_PRICE', 'P_DMF0020_GET_SCM_MST_FUTURE_PRICE_POPUP', 'P_DMF0020_GET_SCM_MST_FUTURE_PRICE_POPUP_DATA', 'P_DMF0020_GET_SCM_MST_FUTURE_PRICE_SAVE_PRICE_POPUP', 'P_DMF0020_GET_SPREAD_TITLE', 'P_DMF0020_GET_SPREAD_TITLE_DATE', 'P_DMF0020_GET_SPREAD_TITLE_SAVE_PRICE', 'P_DMF0020_GET_WEEKDATA', 'P_DMF0020_SAVE_DM_MST_EXCHANGE_RATE_ALL', 'P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL', 'P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_CONVERSION', 'P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP', 'P_PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_SINGLE') ORDER BY 1;
PROMPT [H] PKG_DMF0020 BODY 지문 — 전 10111/479983 (사내 LAST_DDL 2026-09-30 19:25:07 본) · 후 10165/485652
SELECT LN || '/' || CH BODY_FP, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%--[E20260930-DMF0020FXZERO] 원문:%') MARK_LINES, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%/*[E20260930-DMF0020FXZERO]%') MARK_BLOCKS,
       CASE WHEN LN = 10165 AND CH = 485652 THEN 'SKIP — 이미 적용됨'
            WHEN LN = 10111 AND CH = 479983 THEN '적용 — 05 → 11 → 90'
            WHEN (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%--[E20260930-DMF0020FXZERO] 원문:%') = 8 AND (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%/*[E20260930-DMF0020FXZERO]%') = 2 THEN 'SKIP? — 마커 전부 존재하나 지문 상이(타 작업자 변경 병존). 90 으로 확인'
            ELSE '⚠ 11 적용 금지 — 지문 상이(타 작업자 변경). 12 를 수동 반영 (README §4)' END JUDGE
  FROM (SELECT COUNT(*) LN, SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) CH FROM USER_SOURCE WHERE NAME='PKG_DMF0020' AND TYPE='PACKAGE BODY' AND LINE > 1);
PROMPT [H2] 환율 GTT 존재 (Excel: GT_F020_EXCH · Batch: GT_DMF0020_EXCH · 저장: GT_FCSV_RESULTS_MST)
SELECT TABLE_NAME, TEMPORARY, DURATION FROM USER_TABLES WHERE TABLE_NAME IN ('GT_F020_EXCH','GT_DMF0020_EXCH','GT_FCSV_RESULTS_MST') ORDER BY 1;
